questions.reference_sql:
SELECT ROUND(AVG(NetPay), 2) AS 全库人均,
       ROUND(AVG(CASE WHEN CurrencyCode = 'CNY' THEN NetPay END), 2) AS 人民币人均
FROM dbo.HR_SALARY;

